    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({allErrors: true});
  private readonly staticValidators = new Map<string, ValidateFunction>();
  private readonly dynamicValidatorCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(schema: Record<string, unknown>, toolName: string): ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (err) {
      throw new Error(`Tool '${toolName}' has an uncompilable inputSchema: ${(err as Error).message}`, {cause: err});
    }
  }

  private getValidator(name: string, tool: StoredTool): ValidateFunction {
    if (typeof tool.definitionSource !== 'function') {
      return this.staticValidators.get(name)!;
    }
    const definition = tool.definitionSource();
    const schema = definition.inputSchema;
    const cached = this.dynamicValidatorCache.get(schema);
    if (cached) return cached;
    const compiled = this.compileSchema(schema, name);
    this.dynamicValidatorCache.set(schema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.staticValidators.set(resolved.name, this.compileSchema(resolved.inputSchema, resolved.name));
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool's inputSchema before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const validate = this.getValidator(name, tool);

    const valid = validate(input);
    if (!valid) {
      const errors = validate.errors ?? [];
      const message = errors.map(e => `${e.instancePath || '(root)'} ${e.message}`).join('; ');
      log.warn('tool', 'input validation failed', {name, paths: errors.map(e => e.instancePath)});
      return {result: `Tool '${name}' input invalid: ${message}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
  return sentence;
}

interface RoundOutcome {
  stopReason: string;
  text: string;
  usage?: UsageMetadata;
}

// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
async function* streamRound(
  provider: AIProvider,
  request: SendMessageParams,
  pendingToolCalls: ToolCall[]
): AsyncGenerator<MessageChunk, RoundOutcome> {
  let stopReason = '';
  let text = '';
  let usage: UsageMetadata | undefined;

  for await (const chunk of provider.sendMessage(request)) {
    yield chunk;
    collectToolCalls(chunk, pendingToolCalls);
    stopReason = extractStopReason(chunk) ?? stopReason;
    usage = extractUsage(chunk) ?? usage;
    if (chunk.type === 'text') text += chunk.text;
  }

  return {stopReason, text, usage};
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}

function lastUserContent(session: ChatSession): string {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') return entry.content;
  }
  return '';
}

function updateLastUserContent(session: ChatSession, content: string): void {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') {
      entry.content = content;
      return;
    }
  }
}

import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Usage acceptance test.'});
const session = (): ChatSession => ({
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
const TOOL_STOP: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const lookupRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
    async () => 'found'
  );
  return registry;
};

const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

describe('afterModelResponse usage across tool rounds', () => {
  it('reports the summed usage from every provider call in a turn with two tool rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 11, outputTokens: 2, totalTokens: 13})],
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 23, outputTokens: 3, totalTokens: 26})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 37, outputTokens: 5, totalTokens: 42})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });

  it('counts reported rounds while leaving a turn with no reported usage undefined', async () => {
    const reports: Array<UsageMetadata | undefined> = [];
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    };
    const withGaps = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 2, outputTokens: 1, totalTokens: 3})],
        [TOOL_CALL, TOOL_STOP],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 7, outputTokens: 4, totalTokens: 11})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );
    const withoutUsage = createChatOrchestrator(
      scriptedProvider([[{type: 'text', text: 'Done.'}, DONE]]),
      promptBuilder,
      undefined,
      {hooks}
    );

    await withGaps.processMessage(session());
    await withoutUsage.processMessage(session());

    expect(reports).toEqual([{inputTokens: 9, outputTokens: 5, totalTokens: 14}, undefined]);
  });
});

